CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE TABLE organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (organization_id, email));
CREATE TABLE sessions (token_hash BYTEA PRIMARY KEY, csrf_hash BYTEA NOT NULL, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX sessions_expires_at_idx ON sessions(expires_at);
CREATE TABLE pages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL CHECK (kind IN ('primitive', 'scenario', 'subscenario')), primitive_kind TEXT CHECK (primitive_kind IN ('noun', 'verb')), parent_id UUID REFERENCES pages(id), slug TEXT NOT NULL, accepted_revision_id UUID, latest_draft_revision_id UUID, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (organization_id, slug), CHECK ((kind = 'primitive' AND primitive_kind IS NOT NULL AND parent_id IS NULL) OR (kind = 'scenario' AND primitive_kind IS NULL AND parent_id IS NULL) OR (kind = 'subscenario' AND primitive_kind IS NULL AND parent_id IS NOT NULL)));
CREATE TABLE revisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), page_id UUID NOT NULL REFERENCES pages(id) ON DELETE CASCADE, number INTEGER NOT NULL CHECK (number > 0), status TEXT NOT NULL CHECK (status IN ('draft', 'accepted', 'superseded')), title TEXT NOT NULL, body_md TEXT NOT NULL DEFAULT '', aliases TEXT[] NOT NULL DEFAULT '{}', source_urls TEXT[] NOT NULL DEFAULT '{}', provenance TEXT NOT NULL DEFAULT '', base_revision_id UUID REFERENCES revisions(id), created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), accepted_at TIMESTAMPTZ, search_document TSVECTOR NOT NULL DEFAULT ''::tsvector, UNIQUE (page_id, number));
ALTER TABLE pages ADD CONSTRAINT pages_accepted_revision_fk FOREIGN KEY (accepted_revision_id) REFERENCES revisions(id), ADD CONSTRAINT pages_latest_draft_revision_fk FOREIGN KEY (latest_draft_revision_id) REFERENCES revisions(id);
CREATE TABLE bdd_steps (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), revision_id UUID NOT NULL REFERENCES revisions(id) ON DELETE CASCADE, stable_id UUID NOT NULL, position INTEGER NOT NULL CHECK (position >= 0), keyword TEXT NOT NULL CHECK (keyword IN ('given', 'when', 'then', 'and', 'but')), text TEXT NOT NULL, UNIQUE (revision_id, position));
CREATE TABLE page_references (revision_id UUID NOT NULL REFERENCES revisions(id) ON DELETE CASCADE, target_page_id UUID NOT NULL REFERENCES pages(id), relation TEXT NOT NULL, PRIMARY KEY (revision_id, target_page_id, relation));
CREATE TABLE comments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), page_id UUID NOT NULL REFERENCES pages(id) ON DELETE CASCADE, revision_id UUID NOT NULL REFERENCES revisions(id) ON DELETE CASCADE, parent_comment_id UUID REFERENCES comments(id) ON DELETE CASCADE, anchor_kind TEXT, anchor_id TEXT, body TEXT NOT NULL, blocking BOOLEAN NOT NULL DEFAULT false, author_id UUID NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, resolved_by UUID REFERENCES users(id));
CREATE INDEX comments_page_blocking_idx ON comments(page_id) WHERE blocking AND resolved_at IS NULL;
CREATE TABLE votes (revision_id UUID NOT NULL REFERENCES revisions(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), value TEXT NOT NULL CHECK (value IN ('approve', 'reject')), comment_id UUID REFERENCES comments(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (revision_id, user_id), CHECK ((value = 'reject' AND comment_id IS NOT NULL) OR value = 'approve'));
CREATE TABLE revision_embeddings (revision_id UUID PRIMARY KEY REFERENCES revisions(id) ON DELETE CASCADE, embedding vector(1536) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chats (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), user_id UUID NOT NULL REFERENCES users(id), title TEXT NOT NULL, include_drafts BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE chat_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), chat_id UUID NOT NULL REFERENCES chats(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user', 'assistant')), mode TEXT NOT NULL CHECK (mode IN ('qa', 'edit')), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE message_citations (message_id UUID NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE, revision_id UUID NOT NULL REFERENCES revisions(id), position INTEGER NOT NULL, draft BOOLEAN NOT NULL, PRIMARY KEY (message_id, revision_id));
CREATE TABLE ai_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), user_id UUID NOT NULL REFERENCES users(id), chat_id UUID REFERENCES chats(id), mode TEXT NOT NULL CHECK (mode IN ('qa', 'edit', 'transcription')), provider TEXT NOT NULL, model TEXT NOT NULL, status TEXT NOT NULL, error_code TEXT, created_revision_ids UUID[] NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE TABLE audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), actor_id UUID REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX pages_org_kind_idx ON pages(organization_id, kind);
CREATE INDEX pages_slug_trgm_idx ON pages USING gin(slug gin_trgm_ops);
CREATE INDEX revisions_search_idx ON revisions USING gin(search_document);
CREATE INDEX revisions_page_created_idx ON revisions(page_id, created_at DESC);
CREATE INDEX audit_events_org_created_idx ON audit_events(organization_id, created_at DESC);
CREATE INDEX chat_messages_chat_created_idx ON chat_messages(chat_id, created_at);
